function deltaH(prod, react){ // prod/react: array of [enthalpy, coefficient]
  var p=prod.reduce(function(s,x){return s+x[0]*x[1];},0);
  var r=react.reduce(function(s,x){return s+x[0]*x[1];},0);
  return p - r;
}
var EXPORTS = { deltaH:deltaH };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.EnthalpyForgePure = EXPORTS; }
